style.a:
 bên trong lp-label-wrap ── */
.lp-label-wrap a{
  display:inline-block;
  font-size:10px !important; /* override font-size:0 của cha */
  padding:2px 8px;
  font-weight:700;
  border-radius:3px;
  text-decoration:none;
  white-space:nowrap;
  letter-spacing:.3px;
  line-height:1.5;
  background:#e5e7eb; /* fallback màu xám nếu label không khớp */
  color:#374151;
  transition:opacity .2s, transform .15s;
}
.lp-label-wrap a:hover{opacity:.8;transform:translateY(-1px)}

/* ── Màu theo href (CSS-only, hoạt động kể cả khi JS chưa chạy) ── */
.lp-label-wrap a[href*="NEWS"]{background:#dbeafe;color:#1d4ed8}
.lp-label-wrap a[href*="LIFESTYLE"]{background:#f3e8ff;color:#7e22ce}
.lp-label-wrap a[href*="EVENT"]{background:#ffedd5;color:#c2410c}
.lp-label-wrap a[href*="INTERVIEW"]{background:#fce7f3;color:#be185d}
.lp-label-wrap a[href*="COOPERATION"]{background:#dcfce7;color:#166534}
.lp-label-wrap a[href*="USEFUL"]{background:#fef9c3;color:#854d0e}
.lp-label-wrap a[href*="EDUCATION"]{background:#e0e7ff;color:#3730a3}
.lp-label-wrap a[href*="REAL"]{background:#ccfbf1;color:#0f766e}
.lp-label-wrap a[href*="YELLOW"]{background:#fef3c7;color:#92400e}
.lp-label-wrap a[href*="YOUTUBE"]{background:#fee2e2;color:#dc2626}
.lp-label-wrap a[href*="BOARD"]{background:#f0f0f0;color:#555}
.lp-label-wrap a[href*="BANNER"]{background:#e0f2fe;color:#0369a1}
.lp-label-wrap a[href*="SPECIAL"]{background:#ede9fe;color:#4c1d95}
.lp-label-wrap a[href*="CONTRIBUTION"]{background:#ecfdf5;color:#065f46}
.lp-label-wrap a[href*="MARKET"]{background:#fff7ed;color:#9a3412}
.lp-label-wrap a[href*="EBOOK"]{background:#f0fdf4;color:#14532d}
.lp-label-wrap a[href*="PHOTO"]{background:#f0f9ff;color:#0c4a6e}
.lp-label-wrap a[href*="K-FOOD"]{background:#fee2e2;color:#b91c1c}
.lp-label-wrap a[href*="LIFE"]{background:#d1fae5;color:#065f46}
.lp-label-wrap a[href*="PLAZA"]{background:#d1fae5;color:#065f46}
.lp-label-wrap a[href*="VIETNAM"]{background:#fef2f2;color:#991b1b}
.lp-label-wrap a[href*="BUILDING"]{background:#fef3c7;color:#78350f}
.lp-label-wrap a[href*="KOREAN"]{background:#eff6ff;color:#1e40af}
.lp-label-wrap a[href*="TRANSPORTATION"]{background:#f5f3ff;color:#5b21b6}
.lp-label-wrap a[href*="COLLABORATION"]{background:#ecfdf5;color:#064e3b}
.lp-label-wrap a[href*="APPs"]{background:#f0f9ff;color:#0369a1}
.lp-label-wrap a[href*="SOFTWARE"]{background:#faf5ff;color:#6b21a8}
.lp-label-wrap a[href*="TECHNOLOGY"]{background:#eff6ff;color:#1e3a8a}
.lp-label-wrap a[href*="AUDITING"]{background:#fff1f2;color:#9f1239}
.lp-label-wrap a[href*="CONSTRUCTION"]{background:#fefce8;color:#713f12}
.lp-label-wrap a[href*="FURNITURE"]{background:#fff7ed;color:#7c2d12}
.lp-label-wrap a[href*="MEDICATION"]{background:#fdf4ff;color:#701a75}
.lp-label-wrap a[href*="CONSULTING"]{background:#fef9c3;color:#78350f}
.lp-label-wrap a[href*="CONTACT"]{background:#e0f2fe;color:#075985}
.lp-label-wrap a[href*="PLAN"]{background:#ede9fe;color:#5b21b6}
.lp-label-wrap a[href*="PRESIDENT"]{background:#fce7f3;color:#9d174d}
.lp-label-wrap a[href*="PRIORITY"]{background:#fee2e2;color:#991b1b}
.lp-label-wrap a[href*="SOCIAL"]{background:#fdf4ff;color:#7e22ce}
.lp-label-wrap a[href*="VISION"]{background:#f0fdf4;color:#166534}
/* Xóa dấu phẩy/khoảng trắng thêm: dùng JS hoặc font-size:0 trick ở trên */
#lp-latest-list{list-style:none;margin:0;padding:0}
#lp-latest-list li{padding:10px 14px;border-top:1px solid #ccc;transition:background .2s}
#lp-latest-list li:first-child{border-top:none}
#lp-latest-list li:hover{background:#fafafa}
#lp-latest-list li a.lp-ln-title{
  display:flex;align-items:flex-start;gap:7px;
  font-size:14px;font-weight:600;color:#333;
  text-decoration:none;line-height:1.4;
  transition:color .2s;
}
#lp-latest-list li:hover a.lp-ln-title{color:#5a9e1a}
#lp-latest-list li a.lp-ln-title::before{content:"■";color:#8BC34A;font-size:8px;flex-shrink:0;margin-top:4px}
.lp-ln-meta{display:flex;align-items:center;gap:6px;margin-top:4px;padding-left:15px}
.lp-ln-badge{font-size:9px;padding:1px 6px;font-weight:700;border-radius:2px}
.lp-ln-date{font-size:10px;color:#aaa}

/* Blogger native post reset inside our layout */
#main .date-header{display:none}
#main .post{margin:0;padding:0;border:none}
#main p.post-footer{display:none}

/* CATEGORY COLORS */
.cat-NEWS{background:#dbeafe;color:#1d4ed8}
.cat-LIFESTYLE{background:#f3e8ff;color:#7e22ce}
.cat-EVENT{background:#ffedd5;color:#c2410c}
.cat-INTERVIEW{background:#fce7f3;color:#be185d}
.cat-COOPERATION{background:#dcfce7;color:#166534}
.cat-USEFUL{background:#fef9c3;color:#854d0e}
.cat-K-FOOD{background:#fee2e2;color:#b91c1c}
.cat-EDUCATION{background:#e0e7ff;color:#3730a3}
.cat-REAL-ESTATE{background:#ccfbf1;color:#0f766e}
.cat-default{background:#f0f0f0;color:#555}



/* ===== SIDEBAR ===== */
@keyframes fadeSlideUp {
  0% { opacity: 0; transform: translateY(25px); }
  100% { opacity: 1; transform: translateY(0); }
}

#sidebar{float:none;width:auto;margin:0;font-size:16px;line-height:1.6;min-width:0;overflow:hidden}
.lp-sidebar-block{background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.07);overflow:hidden;margin-bottom:14px;animation:fadeSlideUp 0.6s ease-out both}
.lp-sidebar-block:nth-child(1){animation-delay:0.1s}
.lp-sidebar-block:nth-child(2){animation-delay:0.2s}
.lp-sidebar-block:nth-child(3){animation-delay:0.3s}
.lp-sidebar-block:nth-child(4){animation-delay:0.4s}
.lp-sidebar-block:nth-child(5){animation-delay:0.5s}
.lp-sidebar-head{display:flex;align-items:center;gap:8px;padding:9px 14px}
.lp-sidebar-head .icon{font-size:13px}
.lp-sidebar-head .stitle{font-size:15px;font-weight:700;color:#fff}
.lp-head-green{background:#8BC34A}
.lp-head-dark{background:#1f2937}
.lp-head-gray{background:#374151}

.lp-hot-item{display:flex;gap:12px;padding:10px 12px;cursor:pointer;transition:background .2s;border-top:1px solid #ccc;align-items:stretch}
.lp-hot-item:first-of-type{border-top:none}
.lp-hot-item:hover{background:#fafafa}
.lp-hot-thumb{position:relative;width:90px;height:60px;flex-shrink:0;overflow:hidden;border-radius:1px}
.lp-hot-thumb img{width:100%;height:100%;object-fit:cover;transition:transform .3s}
.lp-hot-item:hover .lp-hot-thumb img{transform:scale(1.06)}
.lp-hot-num{position:absolute;top:0;left:0;width:18px;height:18px;background:#8BC34A;color:#fff;font-size:9px;font-weight:700;display:flex;align-items:center;justify-content:center;border-bottom-right-radius:3px;z-index:2}
.lp-hot-item > div:last-child{flex:1;min-width:0;display:flex;flex-direction:column;justify-content:space-between;align-self:stretch}
.lp-hot-title{font-size:14px;font-weight:600;color:#333;line-height:1.25;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;transition:color .2s;margin-top:-3px;margin-bottom:2px}
.lp-hot-item:hover .lp-hot-title{color:#8BC34A}
.lp-hot-date{font-size:12px;color:#aaa;margin-top:auto;display:flex;align-items:center;gap:3px;line-height:1}

.lp-latest-item{padding:10px 14px;cursor:pointer;transition:background .2s;border-top:1px solid #ccc}
.lp-latest-item:first-of-type{border-top:none}
.lp-latest-item:hover{background:#fafafa}
.lp-latest-inner{display:flex;align-items:flex-start;gap:8px}
.lp-latest-dot{width:6px;height:6px;background:#8BC34A;border-radius:50%;flex-shrink:0;margin-top:5px}
.lp-latest-title{font-size:14px;font-weight:600;color:#333;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;transition:color .2s;margin-bottom:3px}
.lp-latest-item:hover .lp-latest-title{color:#8BC34A}
.lp-latest-title a{color:inherit;font-size:inherit;font-weight:inherit}
.lp-latest-date{font-size:12px;color:#aaa}

/* Blogger sidebar widget reset */
.box,.box2,.box3{background:none!important;margin:0!important;padding:0!important}
.sidebar-title{display:none}
.profile-textblock,.profile-img,.profile-data{padding:8px 14px}
#profile-container{background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.07);margin-bottom:14px;padding:0}
#profile-container h2{background:#374151;color:#fff;font-size:15px;font-weight:700;padding:9px 14px;margin:0;border:none}
#profile-container a{color:#8BC34A}

.lp-cats{padding:12px 14px;display:flex;flex-wrap:wrap;gap:6px}
.lp-cat-pill{padding:5px 13px;font-size:13px;font-weight:600;cursor:pointer;border:none;border-radius:3px;display:inline-block;transition:all .2s ease;transform:translateY(0)}
.lp-cat-pill:hover{filter:brightness(0.85);transform:translateY(-2px);box-shadow:0 3px 8px rgba(0,0,0,.15)}

/* Recent posts in sidebar */
#recently{margin:0;padding:0;list-style:none}
#recently li{border-top:1px solid #ccc;padding:9px 14px}
#recently li:first-child{border-top:none}
#recently li a{font-size:14px;font-weight:600;color:#333;transition:color .2s;display:flex;align-items:flex-start;gap:6px}
#recently li a::before{content:"•";color:#8BC34A;font-weight:900;flex-shrink:0}
#recently li a:hover{color:#8BC34A}

/* Archive list */
.archive-list{margin:0;padding:0;list-style:none}
.archive-list li{border-top:1px solid #ccc;padding:8px 14px}
.archive-list li:first-child{border-top:none}
.archive-list li a{font-size:14px;color:#555;transition:color .2s}
.archive-list li a:hover{color:#8BC34A}

/* Contact sidebar */
.lp-contact-item{display:flex;gap:12px;padding:8px 10px;transition:background .2s;border-top:1px solid #ccc;align-items:stretch;min-width:0;overflow:hidden}
.lp-contact-item:first-of-type{border-top:none}
.lp-contact-item:hover{background:#fafafa}
.lp-contact-logo-sidebar{width:100px;height:60px;flex-shrink:0;border:1px solid #eee;border-radius:3px;overflow:hidden;display:flex;align-items:center;justify-content:center;background:#fff}
.lp-contact-logo-sidebar img{width:100%;height:100%;object-fit:contain;padding:4px}
.lp-contact-fallback{width:100%;height:100%;display:flex;align-items:center;justify-content:center;border-radius:3px;font-size:11px;font-weight:800}
.lp-contact-info{flex:1;min-width:0;display:flex;flex-direction:column;justify-content:space-between;align-self:stretch}
.lp-contact-name{font-size:15px;font-weight:700;color:#333;transition:color .2s;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1.2}
.lp-contact-item:hover .lp-contact-name{color:#8BC34A}
.lp-contact-phone{font-size:13px;color:#8BC34A;font-weight:600;line-height:1.2}
.lp-contact-addr{font-size:12px;color:#333;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* ===== SINGLE POST PAGE ===== */
.lp-single-post{background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.07);padding:20px 24px;margin-bottom:16px}
.lp-single-post .post-title{font-size:20px;font-weight:700;color:#222;line-height:1.4;margin-bottom:8px;display:block;-webkit-line-clamp:unset}
.lp-single-post .post-title a{font-size:20px;font-weight:700;color:#222}
.lp-single-post .lp-news-meta{margin-bottom:14px}
.lp-single-post .post-body{font-size:16px;line-height:1.9;color:#333;margin-bottom:16px}
.lp-single-post .post-body img {
  width: 100% !important;
  max-width: 100% !important;
  height: auto !important;
  display: block !important;
  border-radius: 3px;
  margin: 12px 0;
}
.lp-single-post .post-body p{margin-bottom:12px}
.lp-single-post .post-body h2{font-size:17px;font-weight:700;margin:18px 0 8px;color:#222}
.lp-single-post .post-body blockquote{border-left:3px solid #8BC34A;margin:12px 0;padding:8px 14px;background:#f9f9f9;color:#555;font-style:italic}
.lp-single-post .post-footer-info{font-size:13px;color:#aaa;padding-top:12px;border-top:1px solid #f0f0f0;display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.lp-single-post .post-footer-info a{color:#8BC34A}

/* (label badge CSS đã được định nghĩa đầy đủ ở trên) */

/* Comments */
#comments{background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.07);padding:20px 24px;margin-bottom:16px}
#comments h4{font-size:16px;font-weight:700;color:#333;margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid #f0f0f0}
.comment-data{font-size:13px;color:#aaa;margin-bottom:4px}
.comment-poster{font-weight:700;color:#333}
.comment-body{font-size:15px;color:#555;margin-bottom:12px;padding-bottom:12px;border-bottom:1px solid #f0f0f0}
.comment-body:last-child{border-bottom:none}

/* ===== FOOTER ===== */
#footer{clear:both;margin:0;padding:0}
#footer div{background:#f9f9f9;padding:0}
    #footer div {
  border-top: none !important;
}
#footer div div{background:none;padding:16px 12px}
.lp-footer-inner{max-width:1440px;margin:0 auto;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;padding:0 20px}
.lp-footer-logo{font-size:18px;font-weight:800}
.lp-footer-logo .g{color:#8BC34A}
.lp-footer-logo .d{color:#444}
.lp-footer-copy{font-size:12px;color:#888}
.lp-footer-copy a{color:#1a73e8;font-weight:600}
.lp-footer-social{display:flex;gap:14px}
.lp-footer-social a{color:#666;font-size:12px;font-weight:600;transition:color .2s}
.lp-footer-social a:hover{color:#8BC34A}
#footer hr{display:none}
#footer p{margin:0}

/* New Footer Grid */
.lp-footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 32px;
  max-width: 1200px;
  margin: 0 auto;
}
@media (max-width: 900px) {
  .lp-footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 640px) {
  .lp-footer-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
}

/* ===== MOBILE NAV TOGGLE ===== */
#lp-nav-toggle{display:none;background:none;border:none;cursor:pointer;padding:6px;color:#fff;font-size:22px;line-height:1;flex-shrink:0}
#lp-home-btn{display:none}
#lp-nav-mobile-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:1000}
#lp-nav-mobile-overlay.open{display:block}
#lp-mobile-menu{
  display:none;
  position:fixed;
  top:0;left:0;
  width:100%;
  height:100vh;
  background:#fff;
  z-index:1001;
  overflow-y:auto;
  box-shadow:none;
  transform:translateX(-100%);
  transition:transform .3s ease;
  flex-direction:column;
}
#lp-mobile-menu.open{
  display:flex;
  transform:translateX(0);
}
#lp-mobile-menu-head{
  background:#8BC34A;
  padding:14px 16px;
  display:flex;
  align-items:center;
  justify-content:space-between;
}
#lp-mobile-menu-head .mm-logo{font-size:18px;font-weight:800;color:#fff;text-decoration:none}
#lp-mobile-menu-head .mm-logo span{color:#FFD200}
#lp-mobile-menu-close{background:none;border:none;color:#fff;font-size:22px;cursor:pointer;line-height:1;padding:0}
#lp-mobile-menu ul{list-style:none;margin:0;padding:8px 0}
#lp-mobile-menu ul li{
  border-bottom:1px solid #f0f0f0;
  position:relative;
  display:flex;
  flex-wrap:wrap;
  align-items:center;
}
    #lp-mobile-menu ul li > a{
  flex:1;
}
    #lp-mobile-menu ul li > i.mm-arrow{
  padding:12px 16px;
  cursor:pointer;
  flex-shrink:0;
}
    #lp-mobile-menu ul li ul.mm-sub{
  width:100%;
  flex-basis:100%;
}
#lp-mobile-menu ul li a{display:block;padding:12px 18px;font-size:13px;font-weight:700;color:#333;text-transform:uppercase;letter-spacing:.3px}
#lp-mobile-menu ul li a:hover{background:#f5f5f5;color:#8BC34A}
#lp-mobile-menu ul li ul.mm-sub{display:none;background:#fafafa;padding:0}
#lp-mobile-menu ul li.mm-open ul.mm-sub{display:block}
#lp-mobile-menu ul li ul.mm-sub li{border-bottom:1px solid #eee}
#lp-mobile-menu ul li ul.mm-sub li a{padding:10px 28px;font-size:12px;font-weight:600;text-transform:none;color:#555}
#lp-mobile-menu ul li ul.mm-sub li a:hover{color:#8BC34A}
.mm-arrow{
  float:right;
  transition:transform .25s;
  color:#aaa;
  font-style:normal;
  margin-right:8px;
  line-height:1.8;
}
li.mm-open .mm-arrow{transform:rotate(180deg)}

/* ===== RESPONSIVE — TABLET ===== */
@media(max-width:900px){
  .lp-grid{grid-template-columns:1fr!important}
  #sidebar{margin-top:0}
  .lp-slider{height:280px}
  #lp-nav ul#lp-menu{padding:0 4px}
  #lp-menu > li > a{padding:10px 7px;font-size:11px}
}

/* ===== RESPONSIVE — MOBILE ===== */
@media(max-width:640px){
  /* Topbar */
  #header{padding:6px 0!important}
  #blog-title img{height:40px!important}
  .lp-topbar-inner{display:grid!important;grid-template-columns:1fr auto 1fr!important;align-items:center!important;width:100%!important;gap:0!important;padding:0 12px}
  #blog-title{font-size:20px;flex-shrink:0;padding-left:0;justify-self:center!important;margin:0!important;display:flex!important;justify-content:center!important;align-items:center!important}
  #description{display:none}
  .lp-search-wrap{display:contents}
  .lp-lang-flags{gap:6px;display:flex;justify-self:end!important}
  .lp-search-wrap .lp-search-box{display:none !important}
  .lp-flag-btn{width:50px;height:36px}
  .lp-flag-btn img{width:100%;height:100%}

  /* Nav: show hamburger, horizontal menu next to it on mobile */
  #lp-nav-toggle{display:flex!important;align-items:center;justify-content:center;flex-shrink:0;color:#8BC34A!important;font-size:26px!important;padding:6px 0!important;background:none!important;border:none!important;justify-self:start!important}
  #lp-home-btn{display:flex!important;align-items:center;justify-content:center;color:#fff!important;padding:8px 10px!important;flex-shrink:0!important;text-decoration:none!important}
  #lp-home-btn svg{display:block!important;width:20px;height:20px}
  #lp-nav .lp-wrap{display:flex;align-items:center;justify-content:flex-start;padding:0 12px;min-height:40px;overflow:hidden}
  #lp-nav ul#lp-menu{
    display:flex!important;
    flex-direction:row!important;
    flex-wrap:nowrap!important;
    overflow-x:auto!important;
    white-space:nowrap!important;
    flex:1;
    min-width:0;
    margin:0;
    padding:0 0 0 10px;
    scrollbar-width:none;
    -ms-overflow-style:none;
    -webkit-overflow-scrolling:touch;
  }
  #lp-nav ul#lp-menu::-webkit-scrollbar{
    display:none!important;
    width:0!important;
    height:0!important;
  }
  #lp-nav ul#lp-menu > li{
    display:inline-block!important;
    flex:0 0 auto!important;
    border:none!important;
  }
  #lp-nav ul#lp-menu > li > a{
    padding:10px 8px!important;
    font-size:11px!important;
    white-space:nowrap!important;
  }
  #lp-nav ul#lp-menu ul.lp-dropdown{
    display:none!important;
  }

  /* Content */
  #content{padding:12px 8px 30px}
  .lp-slider{height:200px}
  .lp-slide-title{font-size:12px;-webkit-line-clamp:2}
  .lp-slide-sub{display:none}
  .lp-slide-content{padding:12px}
  .lp-slider-arrow{padding:5px 8px;font-size:16px}

  /* Company items */
  .lp-company-logo, .lp-contact-logo { width: 90px !important; height: 60px !important; }
  .lp-company-name{font-size:14px}
  .lp-company-addr{display:none}

  /* News list — mobile: vertical stack (title → labels → excerpt → image) */
  .lp-post-list .post-outer,
  .lp-news-item{flex-direction:column;align-items:stretch;gap:8px;padding:12px 12px}
  .lp-news-thumb,.post-thumbnail{width:100%;height:160px;min-height:0;align-self:stretch;order:4}
  .lp-news-thumb img,.post-thumbnail img{width:100%;height:100%;object-fit:cover}
  .lp-news-body,.post-body-container{display:flex;flex-direction:column;order:1}
  .lp-news-title,.post-title{font-size:13px;font-weight:700;order:1;margin-bottom:4px}
  .lp-news-meta,.post-meta{order:2;margin-bottom:4px}
  .post-excerpt-text, .lp-news-excerpt, .post-snippet{order:3;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;font-size:11px;color:#000 !important;line-height:1.5;margin-top:2px}

  /* Sidebar */
  #sidebar{margin-top:12px;overflow:visible;width:100%}
  .lp-sidebar-block{overflow:hidden}
  .lp-hot-thumb{width:80px;height:52px}
  .lp-hot-title{font-size:13px}

  /* Single post */
  .lp-single-post{padding:14px 12px}
  .lp-single-post .post-title{font-size:16px}
  .lp-single-post .post-body{font-size:13px}

  /* Footer */
  .lp-footer-inner{flex-direction:column;align-items:flex-start;gap:8px}
  .lp-footer-social{flex-wrap:wrap;gap:10px}
}
/* Footer links hover */
#footer a:hover {
  color: #8BC34A !important;
  transform: translateX(4px);
  display: inline-block;
  transition: all .2s ease;
}

/* Footer list items */
#footer ul li a {
  transition: all .2s ease;
  display: inline-block;
}

#footer ul li a:hover {
  color: #8BC34A !important;
  transform: translateX(4px);
}
/* ===== RESPONSIVE — SMALL PHONE ===== */
@media(max-width:380px){
  #blog-title{font-size:17px}
  .lp-search-box input{font-size:11px}
  .lp-flag-btn{width:46px;height:33px}
  .lp-flag-btn img{width:100%;height:100%}
  .lp-slider{height:170px}
  .lp-company-item{padding:10px 10px}
}

/* ===== PAGINATION ===== */
.blog-pager{display:flex;justify-content:center;align-items:center;gap:5px;padding:24px 0;margin-top:8px;flex-wrap:wrap}
.blog-pager .bp-num,
.blog-pager .bp-arrow{
  display:inline-flex;align-items:center;justify-content:center;
  min-width:34px;height:34px;padding:0 10px;
  font-size:13px;font-weight:500;
  border:0.5px solid #d0d0d0;
  border-radius:3px;
  background:#fff;color:#444;
  text-decoration:none;
  transition:background .15s,border-color .15s,color .15s;
  cursor:pointer
}
.blog-pager .bp-num:hover,
.blog-pager .bp-arrow:hover{background:#f4f4f2;border-color:#bbb}
.blog-pager .bp-active{background:#8BC34A!important;border-color:#8BC34A!important;color:#fff!important;cursor:default;font-weight:600}
.blog-pager .bp-arrow{font-size:17px;color:#888}
.blog-pager .bp-arrow:hover{color:#333}
.blog-pager .bp-arrow.disabled{opacity:.3;pointer-events:none;cursor:default}
.blog-pager .bp-ellipsis{display:inline-flex;align-items:center;justify-content:center;min-width:34px;height:34px;font-size:13px;color:#bbb;pointer-events:none;letter-spacing:1px}



/* ===== YELLOWKOREA DIRECTORY PAGE ===== */
#lp-yk-directory { display:none; padding-bottom: 48px; }
#lp-yk-directory.active { display:block; }

#ykSearchInput:focus + .yk-search-icon-wrapper svg {
  color: #2D9B4E !important;
}

/* Hide normal content when YK directory is active */
body.yk-page .lp-slider,
body.yk-page #lp-company-section,
body.yk-page #lp-news-section,
body.yk-page .lp-post-list,
body.yk-page .blog-pager:not(#ykPager) { display:none !important; }

/* Header */
.yk-header { margin-bottom: 15px; }
.yk-header h1 { font-size:30px; font-weight:900; color:#1a1a1a; margin-bottom:6px; font-family:'Noto Sans','Noto Sans KR','Segoe UI',Arial,sans-serif; }
.yk-header p { font-size:15px; color:#777; }


/* Grid - 2 cột, responsive */
.yk-grid { display:grid; grid-template-columns:1fr 1fr; gap:16px; }
@media(max-width:760px){ .yk-grid { grid-template-columns:1fr; } }

/* Business Card - larger horizontal layout */
.yk-card {
  background:#fff;
  border:1px solid #e0e0e0;
  border-radius:3px;
  padding:24px 28px;
  transition: border-color .2s, box-shadow .2s;
  cursor:pointer;
  display:grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto auto;
  gap:0;
}
.yk-card:hover { border-color:#2e7d32; box-shadow:0 4px 20px rgba(46,125,50,.13); }

.yk-card-top { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:10px; grid-column:1/-1; padding-bottom:15px }
.yk-card-name { font-size:22px; font-weight:800; color:#1a1a1a; margin-bottom:5px; font-family:'Noto Sans','Noto Sans KR','Segoe UI',Arial,sans-serif; }
.yk-card-badge {
  display:inline-block;
  background:#2e7d32; color:#fff;
  font-size:10px; font-weight:700;
  padding:2px 8px; border-radius:3px;
  letter-spacing:.5px; margin-left:8px;
  vertical-align:middle;
}
.yk-card-cat { font-size:15px; color:#2e7d32; font-weight:700; letter-spacing:.3px; text-transform:uppercase; }
.yk-card-city { font-size:14px; color:#999; flex-shrink:0; text-align:right; padding-top:4px; }

.yk-card-info { margin-bottom:16px; display:flex; flex-direction:column; gap:8px; grid-column:1/-1; }
.yk-card-info-row { display:flex; align-items:center; gap:8px; font-size:15px; color:#555; }
.yk-card-info-icon { width:16px; height:16px; flex-shrink:0; fill:none; stroke:#2e7d32; stroke-width:2; stroke-linecap:round; stroke-linejoin:round; }

.yk-card-actions { display:flex; gap:10px; grid-column:1/-1; }
.yk-btn-primary {
  flex:1 1 0; background:#2D9B4E; color:#fff;
  border:none; border-radius:3px;
  font-size:14px; font-weight:600;
  padding:12px 0; cursor:pointer;
  transition:background .2s;
  display:flex; align-items:center; justify-content:center; gap:6px;
  text-decoration:none;
}
.yk-btn-primary:hover { background:#2e7d32; }
.yk-btn-secondary {
  flex:1 1 0; background:#fff; color:#1a1a1a;
  border:1px solid #e0e0e0; border-radius:3px;
  font-size:14px; font-weight:600;
  padding:12px 0; cursor:pointer;
  transition:background .2s;
  display:flex; align-items:center; justify-content:center; gap:6px;
  text-decoration:none;
}
.yk-btn-secondary:hover { background:#e8f5e9; }

/* CTA Banner */
.yk-cta {
  margin-top:40px;
  background:linear-gradient(135deg,#c8e6c9,#a5d6a7);
  border:1px solid #81c784;
  border-radius:3px;
  padding:36px 24px;
  text-align:center;
  box-shadow:0 2px 8px rgba(46,125,50,.1);
}
.yk-cta-icon { font-size:36px; margin-bottom:12px; }
.yk-cta h3 { font-size:18px; font-weight:800; color:#1a1a1a; margin-bottom:8px; font-family:'Segoe UI',Arial,sans-serif; }
.yk-cta p { font-size:13px; color:#333; margin-bottom:20px; }
.yk-cta-btn {
  display:inline-flex; align-items:center; gap:8px;
  background:#2e7d32; color:#fff;
  border:none; border-radius:3px;
  padding:12px 28px;
  font-size:13px; font-weight:700;
  cursor:pointer; transition:background .2s;
  box-shadow:0 2px 6px rgba(46,125,50,.3);
  text-decoration:none;
}
.yk-cta-btn:hover { background:#1b5e20; }

/* No results */
.yk-no-result { text-align:center; padding:40px 20px; color:#aaa; font-size:13px; }

/* ── YK Pagination ── */
#ykPager {
  display:flex;
  align-items:center;
  justify-content:center;
  flex-wrap:wrap;
  gap:6px;
  padding:16px 0 8px;
}
#ykPager .bp-arrow,
#ykPager .bp-num {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-width:36px;
  height:36px;
  padding:0 8px;
  border-radius:3px;
  font-size:14px;
  font-weight:600;
  cursor:pointer;
  border:1px solid #e0e0e0;
  background:#fff;
  color:#444;
  transition:all .18s;
  font-family:'Segoe UI',Arial,sans-serif;
}
#ykPager .bp-arrow:hover,
#ykPager .bp-num:hover { background:#e8f5e9; border-color:#a5d6a7; color:#2e7d32; }
#ykPager .bp-active { background:#2e7d32 !important; color:#fff !important; border-color:#2e7d32 !important; box-shadow:0 2px 6px rgba(46,125,50,.3); }
#ykPager .bp-arrow.disabled { opacity:.35; cursor:default; pointer-events:none; }
#ykPager .bp-ellipsis { display:inline-flex; align-items:center; padding:0 4px; color:#aaa; font-size:14px; letter-spacing:2px; }

/* ── YK Star Rating ── */
.yk-stars { display:inline-flex; align-items:center; gap:2px; }
.yk-star { font-size:16px; line-height:1; }
.yk-star.full  { color:#FFB400; }
.yk-star.empty { color:#ddd; }
.yk-rating-score { font-size:13px; font-weight:700; color:#555; margin-left:4px; }
.yk-card-meta { display:flex; flex-direction:column; align-items:flex-end; gap:4px; flex-shrink:0; }
.yk-filter-select {
  height: 44px;
  box-sizing: border-box;
  padding: 0 24px 0 10px;
  border: 1px solid #e0e0e0;
  border-radius: 3px;
  font-size: 13px;
  background: #fff;
  cursor: pointer;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  background-image: url("data:image/svg+xml;utf8,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke=%22%23007aff%22 stroke-width=%223.5%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22%3E%3Cpolyline points=%2218 15 12 21 6 15%22%3E%3C/polyline%3E%3Cpolyline points=%226 9 12 3 18 9%22%3E%3C/polyline%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: right 8px center;
  background-size: 12px 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
}
.yk-filter-select:focus {
  border-color: #2D9B4E;
  box-shadow: 0 0 4px rgba(45,155,78,0.15);
}

/* ── YK Toolbar responsive layout ── */
.yk-toolbar {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 15px;
}
.yk-search-wrapper {
  position: relative;
  width: 100%;
}
.yk-right-controls {
  display: flex;
  flex-direction: column;
  gap: 5px;
  width: 100%;
  box-sizing: border-box;
}
.yk-selects-wrapper {
  display: flex;
  flex-direction: row;
  gap: 5px;
  width: 100%;
  box-sizing: border-box;
}
.yk-selects-wrapper .yk-filter-select {
  flex: 1;
  min-width: 0;
  width: 0;
}
.yk-counter-wrapper {
  align-self: flex-start;
  display: flex;
  align-items: center;
  white-space: nowrap;
}
@media (max-width: 480px) {
  .yk-selects-wrapper .yk-filter-select {
    padding: 0 16px 0 6px !important;
    font-size: 10px !important;
    background-position: right 4px center !important;
    background-size: 10px 10px !important;
  }
  .yk-counter-wrapper span {
    font-size: 11px !important;
  }
}
@media (min-width: 761px) {
  .yk-toolbar {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    align-items: center;
  }
  .yk-search-wrapper {
    width: 100%;
  }
  .yk-right-controls {
    flex-direction: row;
    gap: 12px;
  }
  .yk-selects-wrapper {
    flex: 1;
    gap: 10px;
  }
  .yk-counter-wrapper {
    align-self: center;
    margin-left: auto;
  }
}
