  .goog-te-banner-frame,.goog-te-balloon-frame,#goog-gt-tt,.skiptranslate{display:none!important}
  body{top:0!important}
  .goog-te-gadget{font-size:0!important}
  .lp-flag-btn.lp-lang-active{border-color:#8BC34A!important;box-shadow:0 0 0 2px rgba(139,195,74,.4)}

div.script:
//
window.__lpContactCB = function(data) {
  var listEl = document.getElementById('lp-contact-list');
  var pagerEl = document.getElementById('lp-contact-pager');
  if (!listEl) return;

  var entries = (data && data.feed && data.feed.entry) || [];
  if (!entries.length) {
    listEl.innerHTML = '<div style="padding:15px;text-align:center;font-size:11px;color:#aaa;">Không có dữ liệu.</div>';
    return;
  }

  var COLORS = ['#b8a040','#1d4ed8','#00a3b4','#6b21a8','#ea580c','#047857','#be123c','#b45309','#0e7490'];
  var cards = [];

  for (var i = 0; i < entries.length; i++) {
    var e = entries[i];
    var title = (e.title && e.title.$t) || '';
    var postUrl = '';
    if (e.link) {
      for (var l = 0; l < e.link.length; l++) {
        if (e.link[l].rel === 'alternate') { postUrl = e.link[l].href; break; }
      }
    }

    // Lấy thumbnail từ media$thumbnail (đơn giản & đáng tin cậy nhất)
    var imgSrc = (e.media$thumbnail && e.media$thumbnail.url) ? e.media$thumbnail.url.replace('=s72-c','=s120-c') : '';

    // Parse phone & address từ content
    var phone = '', address = '';
    var ct = (e.content && e.content.$t) || '';
    // Xóa tất cả thẻ HTML và tách dòng
    var plain = ct.replace(/<[^>]+>/g, '\n').replace(/&nbsp;/g,' ').replace(/\u00a0/g,' ');
    var lns = plain.split('\n').map(function(s){ return s.replace(/[●•▶\-]/g,'').trim(); }).filter(function(s){ return s.length > 3; });
    // Dòng đầu có số điện thoại (chứa + hoặc 0 ở đầu)
    for (var li = 0; li < lns.length; li++) {
      if (/^[\+\d\s\-\(\)]{7,}/.test(lns[li])) { phone = lns[li]; break; }
    }
    // Dòng có địa chỉ (chứa từ khóa địa danh)
    for (var li2 = 0; li2 < lns.length; li2++) {
      if (lns[li2] !== phone && lns[li2].length > 10) { address = lns[li2]; break; }
    }

    // Màu fallback theo hash của title
    var hash = 0;
    for (var c = 0; c < title.length; c++) hash = title.charCodeAt(c) + ((hash << 5) - hash);
    var bg = COLORS[Math.abs(hash) % COLORS.length];
    var initials = title.split(' ').slice(0,2).map(function(w){ return w.charAt(0); }).join('').toUpperCase() || 'CT';

    var logoHtml = imgSrc
      ? '<img src="' + imgSrc + '" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\'" alt="' + title + '" loading="lazy" style="width:100%;height:100%;object-fit:contain;padding:4px"/>'
      + '<div class="lp-contact-fallback" style="display:none;background:' + bg + ';color:#fff;font-weight:800;font-size:11px">' + initials + '</div>'
      : '<div class="lp-contact-fallback" style="display:flex;background:' + bg + ';color:#fff;font-weight:800;font-size:11px">' + initials + '</div>';

    cards.push(
      '<a class="lp-contact-item" href="' + postUrl + '">' +
        '<div class="lp-contact-logo-sidebar">' + logoHtml + '</div>' +
        '<div translate="no" class="notranslate lp-contact-info" style="flex:1;min-width:0;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between;align-self:stretch;">' +
          '<div class="lp-contact-name">' + title + '</div>' +
          '<div class="lp-contact-phone">' + (phone || 'Xem chi tiết') + '</div>' +
          '<div class="lp-contact-addr">' + (address || '') + '</div>' +
        '</div>' +
      '</a>'
    );
  }

  // Phân trang
  var PER = 5;
  var total = Math.ceil(cards.length / PER);
  function goPage(pg) {
    listEl.innerHTML = cards.slice((pg-1)*PER, pg*PER).join('');
    // Rebuild pager
    if (total > 1) {
      pagerEl.style.display = 'flex';
      pagerEl.innerHTML = '';
      var mkBtn = function(label, page, active) {
        var a = document.createElement('a');
        a.href = 'javascript:void(0)';
        a.className = 'lp-contact-page' + (active ? ' lp-pg-active' : '');
        a.innerHTML = label;
        a.onclick = function(){ goPage(page); };
        pagerEl.appendChild(a);
      };
      mkBtn('&lt;', Math.max(1, pg-1), false);
      for (var p = 1; p <= total; p++) mkBtn(p, p, p === pg);
      mkBtn('&gt;', Math.min(total, pg+1), false);
    }
  }
  goPage(1);
};
