body.script:
//
// ── SLIDER & HOT NEWS (DYNAMIC) ──
window.initLpSlider = function(){
  var sliderEl=document.getElementById('lpSlider');
  var slides=document.querySelectorAll('#lpSlider .lp-slide');
  var dotsEl=document.getElementById('lpDots');
  var progEl=document.getElementById('lpProgress');
  if(!slides||!slides.length||!dotsEl||!progEl)return;

  var COLS=12, ROWS=8, TRANS_MS=2200, SLIDE_MS=6000;
  var cur=0, total=slides.length, tmr, animating=false;

  /* ── Tạo 1 lớp content cố định luôn ở trên cùng (z-index 20)
       Khi chuyển slide chỉ cần update HTML của lớp này ngay lập tức,
       không bao giờ bị overlay grid che hay bị ẩn ── */
  var contentLayer=document.createElement('div');
  contentLayer.style.cssText='position:absolute;bottom:0;left:0;right:0;z-index:20;pointer-events:none;';
  sliderEl.appendChild(contentLayer);

  /* Ẩn tất cả .lp-slide-overlay và .lp-slide-content gốc
     (gradient + chữ trong từng slide) vì ta dùng contentLayer thay thế */
  slides.forEach(function(sl){
    var ov=sl.querySelector('.lp-slide-overlay');
    var ct=sl.querySelector('.lp-slide-content');
    if(ov) ov.style.display='none';
    if(ct) ct.style.display='none';
  });

  /* Clone gradient overlay vào contentLayer 1 lần */
  var gradDiv=document.createElement('div');
  gradDiv.className='lp-slide-overlay';
  gradDiv.style.cssText='position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.85) 0%,rgba(0,0,0,.2) 55%,transparent 100%);pointer-events:none;';
  contentLayer.appendChild(gradDiv);

  /* Vùng chữ */
  var textDiv=document.createElement('div');
  textDiv.className='lp-slide-content';
  textDiv.style.cssText='position:relative;padding:20px;pointer-events:auto;';
  contentLayer.appendChild(textDiv);

  function getSlideContent(sl){
    var ct=sl.querySelector('.lp-slide-content');
    return ct?ct.innerHTML:'';
  }

  function updateContent(sl){
    textDiv.innerHTML=getSlideContent(sl);
  }

  /* ── Build dots ── */
  dotsEl.innerHTML='';
  for(var i=0;i<total;i++){
    var d=document.createElement('button');
    d.className='lp-dot'+(i===0?' active':'');
    d.setAttribute('data-i',i);
    (function(n){d.onclick=function(){if(animating)return;stop();go(n);start();};})(i);
    dotsEl.appendChild(d);
  }

  /* hiện content slide đầu */
  updateContent(slides[0]);

  function ui(){
    dotsEl.querySelectorAll('.lp-dot').forEach(function(d,i){d.className='lp-dot'+(i===cur?' active':'');});
    progEl.style.width=(((cur+1)/total)*100)+'%';
  }

  function easeOutQuad(t){ return t*(2-t); }

  function buildOverlay(imgSrc, onDone){
    var old=sliderEl.querySelector('.lp-grid-overlay');
    if(old) old.parentNode.removeChild(old);

    var wrap=document.createElement('div');
    wrap.className='lp-grid-overlay';
    wrap.style.cssText='position:absolute;inset:0;z-index:15;display:grid;pointer-events:none;'
      +'grid-template-columns:repeat('+COLS+',1fr);grid-template-rows:repeat('+ROWS+',1fr);';

    var W=sliderEl.offsetWidth||800;
    var H=sliderEl.offsetHeight||360;
    var maxDist=(COLS-1)+(ROWS-1);
    var cellDur=TRANS_MS*0.45;
    var maxDelay=TRANS_MS-cellDur;

    /* Tính background-size cover đúng cách:
       Load ảnh để lấy naturalWidth/naturalHeight, rồi tính như object-fit:cover.
       Nếu ảnh chưa load xong dùng fallback W×H trước, update sau. */
    function computeCoverSize(natW, natH, cW, cH){
      var scaleW=cW/natW, scaleH=cH/natH;
      var scale=Math.max(scaleW,scaleH);
      return {w:Math.round(natW*scale), h:Math.round(natH*scale)};
    }
    function computeCoverOffset(bgW, bgH, cW, cH){
      return {x:Math.round((cW-bgW)/2), y:Math.round((cH-bgH)/2)};
    }

    /* Tạo cells trước với fallback, rồi update khi ảnh load */
    var cells=[];
    for(var r=0;r<ROWS;r++){
      for(var c=0;c<COLS;c++){
        var cell=document.createElement('div');
        cell.dataset.c=c; cell.dataset.r=r;
        cell.style.cssText=
          'background-image:url('+imgSrc+');'
          +'background-size:'+W+'px '+H+'px;'
          +'background-position:0px 0px;'
          +'background-repeat:no-repeat;'
          +'transform:scale(0);'
          +'transform-origin:center center;'
          +'will-change:transform;';
        cells.push(cell);
        wrap.appendChild(cell);
      }
    }

    sliderEl.appendChild(wrap);

    /* Load ảnh để lấy kích thước tự nhiên */
    var probe=new Image();
    probe.onload=function(){
      var sz=computeCoverSize(probe.naturalWidth, probe.naturalHeight, W, H);
      var off=computeCoverOffset(sz.w, sz.h, W, H);
      var cellW=W/COLS, cellH=H/ROWS;
      cells.forEach(function(cell){
        var c=parseInt(cell.dataset.c,10);
        var r=parseInt(cell.dataset.r,10);
        /* offset của ô này = offset cover + dịch trái/lên theo vị trí ô */
        var px=off.x - c*cellW;
        var py=off.y - r*cellH;
        cell.style.backgroundSize=sz.w+'px '+sz.h+'px';
        cell.style.backgroundPosition=px.toFixed(1)+'px '+py.toFixed(1)+'px';
      });
    };
    probe.onerror=function(){/* giữ fallback */};
    probe.src=imgSrc;

    /* Chạy animation sau 1 rAF để DOM đã render */
    requestAnimationFrame(function(){
      cells.forEach(function(cell){
        var c=parseInt(cell.dataset.c,10);
        var r=parseInt(cell.dataset.r,10);
        var dist=r+c;
        var delay=easeOutQuad(dist/maxDist)*maxDelay;
        (function(el,dl){
          setTimeout(function(){
            el.style.transition='transform '+cellDur+'ms cubic-bezier(0.25,0.46,0.45,0.94)';
            el.style.transform='scale(1)';
          },dl);
        })(cell,delay);
      });
    });

    setTimeout(function(){
      if(wrap.parentNode) wrap.parentNode.removeChild(wrap);
      onDone();
    }, TRANS_MS+60);
  }

  function go(n){
    if(animating)return;
    animating=true;
    var next=(n+total)%total;

    var nextImg=slides[next].querySelector('img');
    var imgSrc=nextImg?nextImg.src:'';

    /* Update chữ NGAY LẬP TỨC trước khi grid bắt đầu
       — contentLayer z-index 20 luôn hiển thị, không bị che */
    updateContent(slides[next]);
    ui_next(next);

    buildOverlay(imgSrc, function(){
      /* Khi grid xong: swap ảnh nền slide */
      slides[cur].classList.remove('active');
      slides[cur].style.opacity='';
      slides[cur].style.zIndex='';
      cur=next;
      slides[cur].classList.add('active');
      slides[cur].style.zIndex='2';
      animating=false;
    });
  }

  function ui_next(next){
    dotsEl.querySelectorAll('.lp-dot').forEach(function(d,i){d.className='lp-dot'+(i===next?' active':'');});
    progEl.style.width=(((next+1)/total)*100)+'%';
  }

  function start(){tmr=setInterval(function(){go(cur+1);},SLIDE_MS);}
  function stop(){clearInterval(tmr);}
  window.sliderMove=function(d){stop();animating=false;go(cur+d);start();};
  ui();start();
};

(function(){
  // ── AUTO THUMBNAIL: extract first img from post body (Synchronous for server-rendered posts) ──
  var PLACEHOLDER='https://placehold.co/96x68/f0f0f0/aaa?text=News';
  document.querySelectorAll('.post-outer').forEach(function(card){
    var bodyEl=card.querySelector('.lp-body-src');
    var thumbEl=card.querySelector('.lp-auto-thumb');
    var excerptEl=card.querySelector('.post-excerpt-text');
    if(!bodyEl||!thumbEl)return;
    var html=bodyEl.innerHTML;
    var m=html.match(/<img[^>]+src=["']([^"']+)["']/i);
    thumbEl.src=(m&&m[1])?m[1]:PLACEHOLDER;
    if(!m){thumbEl.style.opacity='0.35';}
    if(excerptEl){
      var tmp=document.createElement('div');
      tmp.innerHTML=html;
      var txt=(tmp.textContent||tmp.innerText||'').replace(/\s+/g,' ').trim();
      excerptEl.textContent=txt.substring(0,110);
      excerptEl.style.cssText='font-size:11px;color:#888;overflow:hidden;display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical;margin-top:2px';
    }
    bodyEl.parentNode.removeChild(bodyEl);
  });

  // ―― Reformat date: "April 25, 2026" → "2026-04-25" (Synchronous) ――
  var MONTHS={January:'01',February:'02',March:'03',April:'04',May:'05',June:'06',July:'07',August:'08',September:'09',October:'10',November:'11',December:'12'};
  document.querySelectorAll('.post-date,.lp-news-date,.lp-ln-date').forEach(function(el){
    var m=(el.textContent||'').trim().match(/^([A-Za-z]+)\s+(\d{1,2}),\s*(\d{4})$/);
    if(m){
      var mon=null; Object.keys(MONTHS).forEach(function(k){ if(k.toLowerCase().indexOf(m[1].toLowerCase())===0) mon=MONTHS[k]; });
      if(mon) el.textContent=m[3]+'-'+mon+(m[2].length===1?'-0':'-')+m[2];
    }
  });

  var perPage = 12;
  var allPosts = [];
  var filteredPosts = [];
  var currentPage = 1;

  var sliderWrap = document.getElementById('lpSliderWrapper');
  var hotWrap = document.getElementById('lpHotNewsWrapper');
  var postListWrap = document.querySelector('.lp-post-list'); // Only exists on Main/Archive
  var pagerWrap = document.getElementById('blog-pager');

  // Detect context
  var loc = location.href;
  var isLabel = loc.indexOf('/search/label/') > -1;
  var currentLabel = '';
  if(isLabel){
    var lm = loc.match(/\/search\/label\/([^\?&#]+)/);
    if(lm) currentLabel = decodeURIComponent(lm[1]);
  }
  var isSearch = loc.indexOf('/search') > -1 && loc.indexOf('?q=') > -1;
  var searchQuery = '';
  if(isSearch){
     var qm = loc.match(/\?q=([^&]+)/);
     if(qm) searchQuery = decodeURIComponent(qm[1]).toLowerCase();
  }

  window.__lpMainAppCB = function(data) {
    var entries = (data.feed && data.feed.entry) || [];
    var excludeLabels = ['CONTACT', 'PRESIDENT'];
    var isExcludePage = (currentLabel && excludeLabels.indexOf(currentLabel.toUpperCase()) > -1);

    for(var i=0; i<entries.length; i++) {
      var entry = entries[i];
      var cats = entry.category || [];
      var labels = cats.map(function(c){ return c.term; });
      var hasExcluded = false;
      if(!isExcludePage) {
        for(var j=0; j<labels.length; j++) {
          if(excludeLabels.indexOf(labels[j].toUpperCase()) > -1) { hasExcluded = true; break; }
        }
      }

      var link = '';
      for(var l=0; l<entry.link.length; l++){
        if(entry.link[l].rel === 'alternate'){ link = entry.link[l].href; break; }
      }

      var imgUrl = entry.media$thumbnail ? entry.media$thumbnail.url.replace(/\/(s\d+|w\d+-h\d+)[^\/]*\//, '/s900/').replace(/\=s\d+[^\/]*$/, '=s900') : '';
      if(!imgUrl) {
         var content = (entry.content && entry.content.$t) || '';
         var imgMatch = content.match(/<img[^>]+src=["']([^"']+)["']/i);
         imgUrl = imgMatch ? imgMatch[1] : 'https://placehold.co/900x500/f0f0f0/aaa?text=News';
      }

      var summaryText = (entry.summary && entry.summary.$t) || (entry.content && entry.content.$t) || '';
      var tmp = document.createElement('div');
      var htmlWithNewlines = summaryText.replace(/<br\s*[\/]?>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<\/div>/gi, '\n');
      tmp.innerHTML = htmlWithNewlines;
      var rawText = (tmp.textContent || tmp.innerText || '').trim();
      var text = rawText.replace(/\s+/g, ' ').trim();
      var excerpt = text.substring(0, 120) + (text.length > 120 ? '...' : '');

      var rawDate = entry.published.$t; // 2026-04-25T...
      var dateStr = rawDate.substring(0, 10);

      allPosts.push({
        title: entry.title.$t,
        url: link,
        img: imgUrl,
        labels: labels,
        date: dateStr,
        excerpt: excerpt,
        rawText: rawText,
        hasExcluded: hasExcluded
      });
    }

    var validGlobal = allPosts.filter(function(p){ return !p.hasExcluded; });

    // 1. Slider
    if(sliderWrap) {
      var sliderHtml = '';
      var sCount = Math.min(4, validGlobal.length);
      for(var s=0; s<sCount; s++){
