      }
      hotWrap.innerHTML = hotHtml;
    }



    // 3. Main Post List & Pagination (AJAX)
    if(postListWrap) {
      filteredPosts = allPosts.filter(function(p){
        if(p.hasExcluded && !isExcludePage) return false;
        if(currentLabel) {
          var match = false;
          for(var i=0; i<p.labels.length; i++){
            if(p.labels[i].toUpperCase() === currentLabel.toUpperCase()) { match=true; break; }
          }
          if(!match) return false;
        }
        if(searchQuery) {
          if(p.title.toLowerCase().indexOf(searchQuery) === -1 && p.excerpt.toLowerCase().indexOf(searchQuery) === -1) return false;
        }
        return true;
      });

      renderPage(1);
    }

    // 4. Latest News Labels & Date (Generate if empty, else enhance)
    var latestList = document.getElementById('lp-latest-list');
    if (latestList) {
      var latestItems = latestList.querySelectorAll('li');
      if (latestItems.length === 0) {
        // On ItemPage, BloggerPreviousItems is empty, so we build it from validGlobal
        var lnHtml = '';
        var lCount = Math.min(5, validGlobal.length);
        for(var i=0; i<lCount; i++){
          var p = validGlobal[i];
          var firstLabel = p.labels.length ? p.labels[0] : '';
          var labelHtml = firstLabel ? '<a href="/search/label/'+encodeURIComponent(firstLabel)+'" style="border-radius:3px;font-size:9px !important;padding:1px 6px;margin-right:2px">'+firstLabel+'</a>' : '';
          lnHtml += '<li data-post-url="'+p.url+'">' +
            '<a class="lp-ln-title" href="'+p.url+'">'+p.title+'</a>' +
            '<div class="lp-ln-meta">' +
              '<span class="lp-label-wrap lp-ln-labels">'+labelHtml+'</span>' +
              '<span class="lp-ln-date">'+p.date+'</span>' +
            '</div>' +
          '</li>';
        }
        latestList.innerHTML = lnHtml;
      } else {
        latestItems.forEach(function(li){
          var url = li.getAttribute('data-post-url');
          if(!url) return;
          var path = url.replace(/^https?:\/\/[^\/]+/i, '').split('?')[0];
          var matched = allPosts.find(function(p){ return p.url.indexOf(path) > -1; });
          if(matched) {
            if(matched.hasExcluded && !isExcludePage) { li.style.display = 'none'; return; }
            var span = li.querySelector('.lp-ln-labels');
            if(span && matched.labels.length) {
              span.innerHTML = '<a href="/search/label/'+encodeURIComponent(matched.labels[0])+'" style="border-radius:3px;font-size:9px !important;padding:1px 6px;margin-right:2px">'+matched.labels[0]+'</a>';
            }
            var dateSpan = li.querySelector('.lp-ln-date');
            if(dateSpan) dateSpan.textContent = matched.date;
          }
        });
      }
    }

    // 5. Contact List (Main & Sidebar)
    var contactMainWrap = document.getElementById('lpContactMainWrap');
    var contactSidebarInner = document.getElementById('lpContactSidebarInner');
    if(contactMainWrap || contactSidebarInner) {
      var contactPosts = allPosts.filter(function(p){
        return p.labels.some(function(l){ return l.toUpperCase() === 'CONTACT'; });
      });
      var mHtml = '', sHtml = '';
      for(var c=0; c<contactPosts.length; c++){
         var p = contactPosts[c];
         var secondLabel = '';
         for(var i=0; i<p.labels.length; i++){
            if(p.labels[i].toUpperCase() !== 'CONTACT') { secondLabel = p.labels[i]; break; }
         }
         if(!secondLabel) secondLabel = 'DEFAULT';

         var pLines = p.rawText ? p.rawText.split('\n').map(function(s){return s.trim();}).filter(Boolean) : [];
         var phone = pLines.length > 0 ? pLines[0] : '';
         var addr = pLines.length > 1 ? pLines.slice(1).join(', ') : '';

         if(contactMainWrap) {
