              '</div>' +
              '<span class="lp-external">↗</span>' +
            '</a>';
         }

         if(contactSidebarInner) {
            var fallback = p.title.substring(0,2).toUpperCase();
            var bgColors = ['#b8a040', '#1d4ed8', '#00a3b4', '#6b21a8', '#c2410c', '#15803d'];
            var bg = bgColors[c % bgColors.length];
            sHtml += '<a class="lp-contact-item" href="'+p.url+'" onclick="jumpToCompany(\''+p.title+'\', event)">' +
              '<div class="lp-contact-logo">' +
                '<img src="'+p.img+'" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\'" alt="'+p.title+'" loading="lazy"/>' +
                '<div class="lp-contact-fallback" style="display:none;background:'+bg+';color:#fff;font-weight:800;font-size:11px">'+fallback+'</div>' +
              '</div>' +
              '<div translate="no" class="notranslate">' +
                '<div class="lp-contact-name">'+p.title+'</div>' +
