            '</a>';
         }
      }
      if(contactMainWrap) contactMainWrap.innerHTML = mHtml;
      if(contactSidebarInner) contactSidebarInner.innerHTML = sHtml;
    }
  };

  function makeBadgeHTML(label) {
    return '<a href="/search/label/' + encodeURIComponent(label) + '">' + label + '</a>';
  }

  function renderPage(page) {
    currentPage = page;
    var start = (page - 1) * perPage;
    var end = start + perPage;
    var pagePosts = filteredPosts.slice(start, end);

    var html = '';
    if(pagePosts.length === 0) {
      html = '<div style="padding:20px;text-align:center;color:#888;">Không có bài viết nào. / No posts found.</div>';
    } else {
      for(var i=0; i<pagePosts.length; i++){
        var p = pagePosts[i];
        var badges = p.labels.map(makeBadgeHTML).join('');
        html += '<div class="post-outer">' +
          '<div class="post-thumbnail">' +
            '<a href="'+p.url+'">' +
              '<img alt="" class="lp-auto-thumb" src="'+p.img+'" loading="lazy" onerror="this.src=\'https://placehold.co/96x68/f0f0f0/aaa?text=News\'"/>' +
            '</a>' +
          '</div>' +
          '<div class="post-body-container">' +
            '<div class="post-meta">' +
              '<span class="lp-label-wrap lp-post-labels">' + badges + '</span>' +
              '<span class="post-date">' + p.date + '</span>' +
            '</div>' +
            '<div class="post-title">' +
              '<a href="'+p.url+'">' + p.title + '</a>' +
            '</div>' +
            '<div class="post-excerpt-text">' + p.excerpt + '</div>' +
          '</div>' +
        '</div>';
      }
    }

    postListWrap.style.opacity = '0.5';
    setTimeout(function() {
      postListWrap.innerHTML = html;
      postListWrap.style.opacity = '1';
      postListWrap.style.transition = 'opacity 0.3s ease';
    }, 100);

    renderPagination();

    if(page > 1) {
       var topPos = postListWrap.previousElementSibling ? postListWrap.previousElementSibling.offsetTop : postListWrap.offsetTop;
       window.scrollTo({ top: topPos - 20, behavior: 'smooth' });
    }
  }

  window.goToPage = function(p) { renderPage(p); };

  function renderPagination() {
    if(!pagerWrap) return;
    var totalPages = Math.ceil(filteredPosts.length / perPage);
    if(totalPages <= 1) { pagerWrap.style.display = 'none'; return; }
    pagerWrap.style.display = 'flex';

    var html = '';
    var startP = Math.max(1, currentPage - 2);
    var endP   = Math.min(totalPages, startP + 4);
    startP     = Math.max(1, endP - 4);

    if(currentPage > 1) html += '<button class="bp-arrow" onclick="goToPage('+(currentPage-1)+')">&#8249;</button>';
    else html += '<button class="bp-arrow disabled">&#8249;</button>';

    if(startP > 1){
      html += '<button class="bp-num" onclick="goToPage(1)">1</button>';
      if(startP > 2) html += '<span class="bp-ellipsis">&middot;&middot;&middot;</span>';
    }

    for(var i = startP; i <= endP; i++){
      if(i === currentPage) html += '<button class="bp-num bp-active">'+i+'</button>';
      else html += '<button class="bp-num" onclick="goToPage('+i+')">'+i+'</button>';
    }

    if(endP < totalPages){
      if(endP < totalPages - 1) html += '<span class="bp-ellipsis">&middot;&middot;&middot;</span>';
      html += '<button class="bp-num" onclick="goToPage('+totalPages+')">'+totalPages+'</button>';
    }

    if(currentPage < totalPages) html += '<button class="bp-arrow" onclick="goToPage('+(currentPage+1)+')">&#8250;</button>';
    else html += '<button class="bp-arrow disabled">&#8250;</button>';

    pagerWrap.innerHTML = html;
  }

  var s = document.createElement('script');
  s.src = __LP_BLOG_URL + 'feeds/posts/summary?alt=json-in-script&max-results=500&callback=__lpMainAppCB';
  document.head.appendChild(s);
})();

  // ―― Reformat date: "April 25, 2026" → "2026-04-25" ――
  var MONTHS={January:'01',February:'02',March:'03',April:'04',May:'05',June:'06',July:'07',August:'08',September:'09',October:'10',November:'11',December:'12'};
  document.querySelectorAll('.post-date,.lp-news-date,.lp-ln-date').forEach(function(el){
    var m=(el.textContent||'').trim().match(/^([A-Za-z]+)\s+(\d{1,2}),\s*(\d{4})$/);
    if(m){
      var mon=null; Object.keys(MONTHS).forEach(function(k){ if(k.toLowerCase().indexOf(m[1].toLowerCase())===0) mon=MONTHS[k]; });
      if(mon) el.textContent=m[3]+'-'+mon+(m[2].length===1?'-0':'-')+m[2];
    }
  });

  // ―― AUTO JUMP TO COMPANY POST ――
  window.jumpToCompany = function(query, event) {
    if(event) event.preventDefault();
    window.__lpJumpQuery = query.toLowerCase().trim();
    var s = document.createElement('script');
    s.src = __LP_BLOG_URL + 'feeds/posts/summary?q=' + encodeURIComponent(query) + '&max-results=10&alt=json-in-script&callback=__lpJumpCB';
    document.head.appendChild(s);
  };
  window.__lpJumpCB = function(data) {
    if(data.feed && data.feed.entry && data.feed.entry.length > 0) {
      var targetEntry = null;
      for(var i=0; i<data.feed.entry.length; i++) {
        if(data.feed.entry[i].title.$t.toLowerCase().trim() === window.__lpJumpQuery) {
          targetEntry = data.feed.entry[i];
          break;
        }
      }
      if(!targetEntry) targetEntry = data.feed.entry[0];

      var link = null;
      for(var j=0; j<targetEntry.link.length; j++){
        if(targetEntry.link[j].rel === 'alternate') {
          link = targetEntry.link[j].href;
          break;
        }
      }
      if(link) window.location.href = link;
    }
  };


