// ── Cookie helper ──
function lpSetCookie(name, value) {
  var host = location.hostname;
  document.cookie = name + '=' + value + ';path=/;domain=' + host;
  document.cookie = name + '=' + value + ';path=/;domain=.' + host;
  document.cookie = name + '=' + value + ';path=/';
}
function lpGetCookie(name) {
  var m = document.cookie.match('(?:^|;)\\s*' + name + '=([^;]+)');
  return m ? decodeURIComponent(m[1]) : '';
}

// ── Cookie expirer (aggressive) ──
function lpExpireCookie(name) {
  var host = location.hostname;
  var past = 'expires=Thu, 01 Jan 1970 00:00:00 UTC';
  var hostParts = host.split('.');

  // Try expiring on current path
  document.cookie = name + '=;' + past + ';path=/';
  document.cookie = name + '=;' + past + ';path=/;domain=' + host;
  document.cookie = name + '=;' + past + ';path=/;domain=.' + host;

  // Try expiring on parent domains if applicable (e.g. lifeplaza.net)
  if (hostParts.length > 2) {
    var parentDomain = hostParts.slice(1).join('.');
    document.cookie = name + '=;' + past + ';path=/;domain=' + parentDomain;
    document.cookie = name + '=;' + past + ';path=/;domain=.' + parentDomain;
  }
}

// ── Lang switcher ──
window.lpSwitchLang = function(lang) {
  if (lang === 'ko') {
    lpExpireCookie('googtrans');
    // For good measure, try setting to 'auto' or empty
    lpSetCookie('googtrans', '');

    // Also try GT widget own restore
    try {
      var sel = document.querySelector('.goog-te-combo');
      if (sel) { sel.value = ''; sel.dispatchEvent(new Event('change')); }
    } catch(e) {}
  } else {
    lpSetCookie('googtrans', '/ko/' + lang);
  }

  // Delay navigation slightly to allow cookie changes to register
  setTimeout(function() {
    window.location.href = location.pathname + location.search;
  }, 100);
};


// ── On load: restore active flag from cookie ──
(function() {
  var gt = lpGetCookie('googtrans');
  var activeLang = 'ko';
  if (gt && gt.indexOf('/ko/vi') !== -1) activeLang = 'vi';

  function markActive() {
    var btn = (activeLang === 'vi')
      ? document.getElementById('lpFlagVN')
      : document.getElementById('lpFlagKR');
    if (btn) btn.classList.add('lp-lang-active');


  }

  // ── Protect navbar from translation ──
  function markNoTranslate() {
    document.querySelectorAll(
      '#lp-nav a, #lp-menu a, #lp-mobile-menu a, #lp-nav-toggle'
    ).forEach(function(el) {
      el.setAttribute('translate', 'no');
      el.classList.add('notranslate');
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() { markActive(); markNoTranslate(); });
  } else {
    markActive(); markNoTranslate();
  }
})();

// ── Google Translate init ──
window.googleTranslateElementInit = function() {
  new google.translate.TranslateElement({
    pageLanguage: 'ko',
    includedLanguages: 'vi,ko',
    autoDisplay: false,
    layout: google.translate.TranslateElement.InlineLayout.SIMPLE
  }, 'google_translate_element');
};
